import pandas as pd

CASO_HUMO = {
    "distrito": "Miraflores",
    "area_m2": 85.0,
    "habitaciones": 2,
    "antiguedad": 12,
}


def verificar_arranque(modelo) -> float:
    """Falla al arrancar si el pipeline devuelve algo absurdo."""
    precio = float(modelo.predict(pd.DataFrame([CASO_HUMO]))[0])
    if not 300 <= precio <= 5000:
        raise RuntimeError(
            f"Predicción de humo fuera de rango: {precio:.2f} USD. "
            "Revisa el artefacto y las versiones de scikit-learn."
        )
    return precio
